import{_ as i,C as a,o as r,c as o,a4 as t,E as n}from"./chunks/framework.BE47AOxC.js";const _=JSON.parse('{"title":"Installer Teuthis-CMS","description":"","frontmatter":{"title":"Installer Teuthis-CMS"},"headers":[],"relativePath":"installer/index.md","filePath":"installer/index.md"}'),l={name:"installer/index.md"};function u(d,e,c,m,p,h){const s=a("ProfilSelecteur");return r(),o("div",null,[e[0]||(e[0]=t('<h1 id="installer-teuthis-cms" tabindex="-1">Installer Teuthis-CMS <a class="header-anchor" href="#installer-teuthis-cms" aria-label="Permalink to &quot;Installer Teuthis-CMS&quot;">​</a></h1><p>Le plus simple est l&#39;<strong>installation guidée</strong> : une commande, qui vérifie le serveur, pose quelques questions et fait tout le reste. Elle s&#39;adresse à un référent informatique qui sait copier une commande sur un serveur Linux, sans être développeur.</p><h2 id="prerequis" tabindex="-1">Ce qu&#39;il vous faut <a class="header-anchor" href="#prerequis" aria-label="Permalink to &quot;Ce qu&#39;il vous faut {#prerequis}&quot;">​</a></h2><p>Il vous faut un serveur <strong>Debian 12, Ubuntu 22.04 ou Ubuntu 24.04</strong> (amd64 ou arm64 ; 2 Go de mémoire au minimum, 4 Go conseillés ; 20 Go de disque libre), un accès administrateur (<code>sudo</code>), et un nom <code>cms.&lt;votre domaine&gt;</code> qui <strong>pointe déjà</strong> sur ce serveur (enregistrement DNS A, et AAAA s&#39;il a de l&#39;IPv6). Pour le profil « Blog et presse », qui installe aussi le site public, un second nom, <code>www.&lt;votre domaine&gt;</code> (ou tout autre nom choisi pour le site) ; pour le profil « Sur mesure », un second nom, <code>api.&lt;votre domaine&gt;</code>.</p><p>Les prérequis de l&#39;installation manuelle (Docker, noms de domaine, ports) sont sur la page <a href="/teuthis-cms-distribution/installer/prerequis">Prérequis</a>.</p><h2 id="choisir-son-profil" tabindex="-1">Choisir son profil <a class="header-anchor" href="#choisir-son-profil" aria-label="Permalink to &quot;Choisir son profil {#choisir-son-profil}&quot;">​</a></h2><p>Le profil est l&#39;usage de l&#39;instance : il décide des extensions installées avec elle. Choisissez le vôtre, la commande s&#39;adapte. L&#39;installateur vous demandera ensuite les noms de domaine et le reste, et vérifie tout avant de rien modifier.</p>',7)),n(s),e[1]||(e[1]=t('<p>L&#39;adresse <code>releases/latest/download</code> mène toujours à l&#39;installateur de la dernière version. Pour une version précise, remplacez <code>latest/download</code> par <code>download/vX.Y.Z</code> (les versions sont sur la page <a href="/teuthis-cms-distribution/versions/">Versions</a>). Toutes les options de l&#39;installateur sont sur la page <a href="/teuthis-cms-distribution/installer/options">Options de l&#39;installateur</a>.</p><h2 id="et-ensuite" tabindex="-1">Et ensuite <a class="header-anchor" href="#et-ensuite" aria-label="Permalink to &quot;Et ensuite {#et-ensuite}&quot;">​</a></h2><ul><li><a href="/teuthis-cms-distribution/installer/guide-pas-a-pas">Installation guidée</a> : ce que l&#39;installateur vérifie, demande, fait et affiche à la fin.</li><li><a href="/teuthis-cms-distribution/installer/installation-manuelle">Installation manuelle</a> : les mêmes étapes à la main, pour les comprendre ou les adapter.</li><li><a href="/teuthis-cms-distribution/documentation/referent/">Guide du référent</a> : sauvegarde, mise à jour, dépannage.</li></ul>',3))])}const v=i(l,[["render",u]]);export{_ as __pageData,v as default};
